UPDATE public.profiles SET specialty = 'Orthopedics', bio = 'MBBS, FCPS (Orthopedics). Consultant orthopedics specialist at MediSight Clinic Rawalpindi with 10 years of clinical experience.', consultation_fee = 2800, services = '["Orthopedics consultation", "Diabetes risk assessment", "Follow-up review"]'::jsonb, first_name = 'Omar', last_name = 'Farooq', contact_number = '0300-2000110', phone = '0300-2000110', availability_status = 'available' WHERE id = 'd0000000-0000-4000-8000-000000000110';
