-- 4) Doctor verification rows (public.doctors) ------------------------
ON CONFLICT (user_id) DO NOTHING;

-- 5) Patient portal details -------------------------------------------
UPDATE public.patient_profiles SET gender = 'Female', date_of_birth = DATE '1975-05-15' WHERE user_id = 'd0000000-0000-4000-8000-000000000201';
UPDATE public.patient_profiles SET gender = 'Female', date_of_birth = DATE '1950-05-04' WHERE user_id = 'd0000000-0000-4000-8000-000000000202';
UPDATE public.patient_profiles SET gender = 'Female', date_of_birth = DATE '1959-05-10' WHERE user_id = 'd0000000-0000-4000-8000-000000000203';
UPDATE public.patient_profiles SET gender = 'Male', date_of_birth = DATE '1973-06-12' WHERE user_id = 'd0000000-0000-4000-8000-000000000204';
UPDATE public.patient_profiles SET gender = 'Male', date_of_birth = DATE '1971-03-21' WHERE user_id = 'd0000000-0000-4000-8000-000000000205';
UPDATE public.patient_profiles SET gender = 'Female', date_of_birth = DATE '1952-06-29' WHERE user_id = 'd0000000-0000-4000-8000-000000000206';
