UPDATE public.patient_profiles SET gender = 'Female', date_of_birth = DATE '2001-12-08' WHERE user_id = 'd0000000-0000-4000-8000-000000000208';

-- 6) Clinical patient records (public.patients) ------------------------
ON CONFLICT (id) DO NOTHING;

-- 7) Latest vitals ------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- 8) Diagnosis history --------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- 9) Doctor-patient assignments ------------------------------------------
ON CONFLICT DO NOTHING;

-- 10) Stored risk assessments (public.predictions) ------------------------
ON CONFLICT (id) DO NOTHING;

-- 11) Explanations for each assessed patient's latest assessment -----------
ON CONFLICT (id) DO NOTHING;

-- 12) Appointments (portal patients x doctors) ------------------------------
ON CONFLICT (id) DO NOTHING;

COMMIT;

