--          (SELECT count(*) FROM public.patients WHERE mrn LIKE 'DEMO-%') AS demo_patients,
--          (SELECT count(*) FROM public.predictions pr JOIN public.patients pa ON pa.id = pr.patient_id WHERE pa.mrn LIKE 'DEMO-%') AS demo_predictions;